begin;
select plan(15);
insert into auth.users(id,is_anonymous) values('f4000000-0000-4000-8000-000000000001',true),('f4000000-0000-4000-8000-000000000002',true),('f4000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','f4000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"is_anonymous":true}',true);
select public.create_code_band('Delete test','Leader','기타','1234','112233');
select set_config('test.del.band',public.current_band_identity()->>'band_id',true);
select set_config('test.del.code',public.band_login_settings()->>'code',true);
-- Since 023 only members who saved a date attend it: the leader opts in to the plan days used below.
select public.save_band_availability((select jsonb_agg(jsonb_build_object('date',((now() at time zone 'Asia/Seoul')::date+n)::text)) from generate_series(1,2) n));
select set_config('test.del.song',public.add_song(current_setting('test.del.band')::uuid,'Delete me','Artist')::text,true);
select public.set_song_confirmation(current_setting('test.del.song')::bigint,true);
select public.vote_band_song(current_setting('test.del.song')::bigint,'no','wrong reason');
select public.update_song_difficulty(current_setting('test.del.song')::bigint,'기타',3::smallint,0);
select set_config('test.del.extra',public.add_song(current_setting('test.del.band')::uuid,'No votes needed','Artist')::text,true);
select is(public.band_pending_vote_count(),1,'unconfirmed song counts as pending');
select public.set_song_confirmation(current_setting('test.del.extra')::bigint,true);
select is(public.band_pending_vote_count(),0,'confirmed song needs no personal vote');
select public.set_song_confirmation(current_setting('test.del.extra')::bigint,false);
select is(public.band_pending_vote_count(),1,'unconfirmed song returns to pending with original votes intact');
select public.delete_band_song(current_setting('test.del.extra')::bigint);

select set_config('test.del.plan',public.save_rehearsal_plan(current_setting('test.del.band')::uuid,(now() at time zone 'Asia/Seoul')::date+1,array[current_setting('test.del.song')::bigint],(public.band_planning_context()->>'version')::bigint,null,null,false)::text,true);
select set_config('request.jwt.claim.sub','f4000000-0000-4000-8000-000000000002',true);
select public.begin_band_access(current_setting('test.del.code'),'1234');select public.register_band_profile('Member','베이스','246810');
-- The member also attends the edited date, so the later edit stays a full-attendance save.
select public.save_band_availability(jsonb_build_array(jsonb_build_object('date',((now() at time zone 'Asia/Seoul')::date+2)::text)));
select throws_ok($$select public.delete_band_song(current_setting('test.del.song')::bigint)$$,'P0001','FORBIDDEN','ordinary member cannot delete');
select set_config('request.jwt.claim.sub','f4000000-0000-4000-8000-000000000003',true);
select public.create_code_band('Other band','Other leader','기타','1234','556677');
select throws_ok($$select public.delete_band_song(current_setting('test.del.song')::bigint)$$,'P0001','FORBIDDEN','other band leader cannot delete');
select set_config('request.jwt.claim.sub','f4000000-0000-4000-8000-000000000001',true);
select set_config('test.del.version',public.band_planning_context()->>'version',true);
select lives_ok($$select public.delete_band_song(current_setting('test.del.song')::bigint)$$,'own leader can delete confirmed candidate');
select is((select count(*)::int from public.songs where id=current_setting('test.del.song')::bigint),0,'song removed');
select is((select count(*)::int from public.band_song_votes where song_id=current_setting('test.del.song')::bigint),0,'live votes and reasons removed');
select is((select count(*)::int from public.song_difficulties where song_id=current_setting('test.del.song')::bigint),0,'difficulty records removed');
select ok((public.band_planning_context()->>'version')::bigint>current_setting('test.del.version')::bigint,'deletion invalidates stale planning forms');
select is((select title_snapshot from public.confirmed_plan_songs where plan_id=current_setting('test.del.plan')::uuid),'Delete me','existing plan snapshot retained');
select lives_ok($$select public.save_rehearsal_plan(current_setting('test.del.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,array[current_setting('test.del.song')::bigint],(public.band_planning_context()->>'version')::bigint,current_setting('test.del.plan')::uuid,1,false)$$,'plan containing deleted song remains editable');
select throws_ok($$select public.delete_band_song(current_setting('test.del.song')::bigint)$$,'P0001','SONG_NOT_FOUND','second deletion is rejected');
select ok(not has_function_privilege('anon','public.delete_band_song(bigint)','execute'),'anon cannot delete');
select ok(not has_table_privilege('authenticated','public.songs','DELETE'),'direct table deletion cannot bypass RPC');
select * from finish();rollback;
